<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/functions.php'; require_role(['student']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$app=(int)$_POST['application_id'];$rating=max(1,min(5,(int)$_POST['rating']));$comment=trim($_POST['comment']??'');$s=$pdo->prepare("INSERT INTO feedback(application_id,rating,comment) SELECT id,?,? FROM volunteer_applications WHERE id=? AND student_id=? AND status='approved'");$s->execute([$rating,$comment,$app,current_user()['id']]);flash($s->rowCount()?'Feedback submitted.':'Feedback could not be submitted for this application.','success');redirect('feedback.php');}
$s=$pdo->prepare("SELECT va.id,e.title FROM volunteer_applications va JOIN events e ON e.id=va.event_id LEFT JOIN feedback f ON f.application_id=va.id WHERE va.student_id=? AND va.status='approved' AND f.id IS NULL");$s->execute([current_user()['id']]);$eligible=$s->fetchAll();require __DIR__.'/includes/header.php';?>
<section class="page-heading"><span class="eyebrow">YOUR EXPERIENCE</span><h1>Event feedback</h1><p>Share feedback after participating in an event.</p></section>
<div class="form-card"><?php if(!$eligible):?><p>No approved event is currently waiting for feedback.</p><?php else:?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Event<select name="application_id"><?php foreach($eligible as $ev):?><option value="<?=$ev['id']?>"><?=e($ev['title'])?></option><?php endforeach;?></select></label><label>Rating<select name="rating"><option value="5">5 - Excellent</option><option value="4">4 - Very good</option><option value="3">3 - Good</option><option value="2">2 - Fair</option><option value="1">1 - Poor</option></select></label><label>Comments<textarea name="comment" rows="4"></textarea></label><button class="btn btn-primary">Submit feedback</button></form><?php endif;?></div>
<?php require __DIR__.'/includes/footer.php';?>
